<template><section class="ttt"><header><button @click="$router.push('/personal/games')">← 游戏大厅</button><h1>井字棋</h1><select v-model="ai" @change="reset"><option :value="true">对战电脑</option><option :value="false">双人对战</option></select></header><div class="status">{{ status }}</div><div class="board"><button v-for="(_,i) in cells" :key="i" :class="cells[i]" @click="play(i)">{{ cells[i] }}</button></div><button class="again" @click="reset">重新开始</button></section></template>
<script setup lang="ts">import{computed,ref}from'vue';const cells=ref(Array(9).fill('')),xTurn=ref(true),done=ref(false),ai=ref(true);const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];const winner=computed(()=>{for(const[a,b,c]of lines)if(cells.value[a]&&cells.value[a]===cells.value[b]&&cells.value[a]===cells.value[c])return cells.value[a];return''});const status=computed(()=>winner.value?`${winner.value} 获胜！`:done.value?'平局':`轮到 ${xTurn.value?'X':'O'}`);function play(i:number){if(cells.value[i]||winner.value||done.value)return;cells.value[i]=xTurn.value?'X':'O';finish();if(ai.value&&!xTurn.value&&!done.value)setTimeout(bot,250)}function finish(){if(winner.value){done.value=true;return}if(cells.value.every(Boolean)){done.value=true;return}xTurn.value=!xTurn.value}function bot(){const empty=cells.value.map((v,i)=>v?-1:i).filter(i=>i>=0);play(empty[~~(Math.random()*empty.length)])}function reset(){cells.value=Array(9).fill('');xTurn.value=true;done.value=false}</script>
<style scoped>.ttt{max-width:500px;margin:auto;text-align:center;padding:15px}.ttt header{display:flex;justify-content:space-between;align-items:center}.ttt button,.ttt select{border:1px solid var(--c-border);background:var(--c-bg-card);color:var(--c-text-2);border-radius:8px;padding:9px}.ttt h1{color:var(--c-text)}.status{font-size:22px;color:var(--c-purple);font-weight:700;margin:35px}.board{display:grid;grid-template-columns:repeat(3,110px);justify-content:center}.board button{height:110px;border-radius:0;font-size:55px;font-weight:800}.board .X{color:var(--c-purple)}.board .O{color:var(--c-cyan)}.again{margin-top:25px!important;padding:11px 28px!important}@media(max-width:420px){.board{grid-template-columns:repeat(3,90px)}.board button{height:90px}.ttt header{flex-wrap:wrap}.ttt header>button{width:100%;text-align:left}}</style>
